final class OidcAcceptance {
 static final String API="/api/openservice/federation";
 static Map<String,String> query(String raw){var out=new LinkedHashMap<String,String>();for(String part:raw.split("&")){var pair=part.split("=",2);out.put(URLDecoder.decode(pair[0],StandardCharsets.UTF_8),pair.length==1?"":URLDecoder.decode(pair[1],StandardCharsets.UTF_8));}return out;}
 static final class Provider implements AutoCloseable {
  final HttpServer server;final ConfigurableEnvironment environment;final String property="oidc-"+id();final Map<String,Object> settings=new ConcurrentHashMap<>();final Map<String,Map<String,String>> codes=new ConcurrentHashMap<>();
  final RSAKey key;volatile String mode="good",subject="employee-123";volatile Map<String,Object> claims=Map.of();volatile Map<String,String> lastToken=Map.of();volatile Runnable afterToken=()->{};volatile byte[] tokenOverride=null,keyOverride=null;int tokenCalls=0;final String origin;
  Provider(Store store,String callbackBase)throws Exception {
   environment=(ConfigurableEnvironment)store.environment;key=new RSAKeyGenerator(2048).keyID("current-key").generate();server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);origin="http://127.0.0.1:"+server.getAddress().getPort();
   settings.putAll(map("OIDC_ENABLED","true","OIDC_ISSUER",origin,"OIDC_CLIENT_ID","test-client","OIDC_CLIENT_SECRET","synthetic-secret","OIDC_AUTHORIZATION_URL",origin+"/authorize","OIDC_TOKEN_URL",origin+"/token","OIDC_JWKS_URL",origin+"/keys","PUBLIC_BASE_URL",callbackBase));environment.getPropertySources().addFirst(new MapPropertySource(property,settings));
   server.createContext("/authorize",x->{var args=query(x.getRequestURI().getRawQuery());String code=id();codes.put(code,args);x.getResponseHeaders().set("Location",args.get("redirect_uri")+"?code="+code+"&state="+args.get("state")+"&iss="+URLEncoder.encode(origin,StandardCharsets.UTF_8));x.sendResponseHeaders(302,-1);x.close();});
   server.createContext("/token",x->{try{tokenCalls++;lastToken=query(new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));var original=codes.remove(lastToken.get("code"));if(original==null || !lastToken.getOrDefault("client_id","").equals("test-client") || !lastToken.getOrDefault("client_secret","").equals("synthetic-secret") || !lastToken.getOrDefault("redirect_uri","").equals(original.get("redirect_uri")) || !Base64.getUrlEncoder().withoutPadding().encodeToString(org.apache.commons.codec.digest.DigestUtils.sha256(lastToken.getOrDefault("code_verifier",""))).equals(original.get("code_challenge"))){reply(x,400,"{}");return;}afterToken.run();if(mode.equals("error")){reply(x,503,"private-provider-error");return;}if(mode.equals("redirect")){x.getResponseHeaders().set("Location",origin+"/private");reply(x,302,"{}");return;}byte[] body=tokenOverride==null?JSON.writeValueAsBytes(map("id_token",token(original.get("nonce")))):tokenOverride;reply(x,200,new String(body,StandardCharsets.UTF_8));}catch(Exception e){reply(x,500,"test-provider-failure");}});
   server.createContext("/keys",x->{try{reply(x,200,keyOverride==null?new JWKSet(key.toPublicJWK()).toString():new String(keyOverride,StandardCharsets.UTF_8));}catch(Exception e){x.close();}});server.start();
  }
  String token(String nonce)throws Exception {long now=System.currentTimeMillis();var values=new LinkedHashMap<String,Object>(map("iss",origin,"sub",subject,"aud",List.of("test-client"),"iat",now/1000,"exp",now/1000+120,"nonce",nonce));values.putAll(claims);if(mode.equals("unsigned"))return new PlainJWT(JWTClaimsSet.parse(JSON.writeValueAsString(values))).serialize();var header=new JWSHeader.Builder(mode.equals("algorithm")?JWSAlgorithm.RS512:JWSAlgorithm.RS256);if(!mode.equals("missing-kid"))header.keyID(mode.equals("unknown-key")?"unknown":mode.equals("empty-kid")?"":"current-key");var jwt=new JWSObject(header.build(),new Payload(JSON.writeValueAsString(values)));jwt.sign(new RSASSASigner(key));return jwt.serialize();}
  static void reply(HttpExchange x,int status,String body)throws java.io.IOException {byte[] bytes=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(status,bytes.length);x.getResponseBody().write(bytes);x.close();}
  public void close(){server.stop(0);environment.getPropertySources().remove(property);}
 }
 static Map<String,Object> binding(int revision,String username,String subject,boolean remove){return map("revision",revision,"username",username,"subject",subject,"remove",remove);}
 static String setup(WorkflowSupport h)throws Exception {h.account("FederatedUser","agent");return objects(result(h.json("POST",API,binding(0,"FederatedUser","employee-123",false),auth("admin"))).get("bindings")).getFirst().get("binding_id").toString();}
 static String begin(WorkflowSupport h)throws Exception {var login=h.get("/login",null);var response=h.form("/oidc/start",map("csrf",csrf(login)),null);assertEquals(200,response.statusCode(),html(response));var match=java.util.regex.Pattern.compile("id=\"oidc-continue\"[^>]*href=\"([^\"]+)\"").matcher(html(response));assertTrue(match.find(),html(response));return match.group(1).replace("&amp;","&");}
 static String returned(WorkflowSupport h,String authorization)throws Exception {var response=h.client.send(HttpRequest.newBuilder(URI.create(authorization)).GET().build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(302,response.statusCode());return response.headers().firstValue("location").orElseThrow().substring(h.base().length());}
 static HttpResponse<byte[]> login(WorkflowSupport h)throws Exception{return h.get(returned(h,begin(h)),null);}
 static void run(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){String binding=setup(h);String start=begin(h);var params=query(URI.create(start).getRawQuery());assertEquals("S256",params.get("code_challenge_method"));assertEquals("code",params.get("response_type"));assertEquals(h.base()+"/oidc/callback",params.get("redirect_uri"));assertFalse(start.contains("synthetic-secret"));String callback=returned(h,start);var response=h.get(callback,null);assertEquals(302,response.statusCode(),html(response));assertEquals("/",response.headers().firstValue("location").orElseThrow());assertEquals(200,h.get("/",null).statusCode());assertTrue(html(h.get("/account",null)).contains("FederatedUser"));assertEquals(403,h.get(API,null).statusCode());assertEquals(401,h.get(callback,null).statusCode());assertEquals(1,p.tokenCalls);assertEquals(64,p.lastToken.get("code_verifier").length());new Store(h.environment);assertEquals(200,h.get("/",null).statusCode());
   try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_oidc_challenge"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_auth_event WHERE mechanism='oidc' AND outcome='succeeded'"));assertFalse(JSON.writeValueAsString(db.all("SELECT * FROM os_auth_event")).contains("synthetic-secret"));}
   result(h.json("POST",API+"/"+binding,binding(1,"FederatedUser","employee-456",false),auth("admin")));assertEquals(302,h.get("/",null).statusCode());assertEquals(401,login(h).statusCode());p.subject="employee-456";assertEquals(302,login(h).statusCode());assertEquals(200,h.get("/",null).statusCode());p.settings.put("OIDC_ENABLED","false");assertEquals(302,h.get("/",null).statusCode());h.login("admin");assertEquals(200,h.get(API,null).statusCode());assertFalse(html(h.get("/login",null)).contains("Sign in with your organization"));
  }
 }
 static void configuration(WorkflowSupport h)throws Exception {
  assertEquals(200,h.get(API,auth("admin")).statusCode());assertFalse((Boolean)object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));assertEquals(503,h.form("/oidc/start",map("csrf",csrf(h.get("/login",null))),null).statusCode());h.account("FederationReader","reader");assertEquals(403,h.get(API,auth("FederationReader")).statusCode());assertEquals(405,h.json("DELETE",API,map(),auth("admin")).statusCode());assertEquals(400,h.get(API+"?unknown=1",auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());
  try(var p=new Provider(h.store,h.base())){String id=setup(h);assertEquals(200,h.get("/admin/federation",auth("admin")).statusCode());assertFalse(html(h.get(API,auth("admin"))).contains("synthetic-secret"));assertEquals(409,h.json("POST",API,binding(0,"FederatedUser","other",false),auth("admin")).statusCode());h.account("FederatedOther","agent");assertEquals(409,h.json("POST",API,binding(0,"FederatedOther","employee-123",false),auth("admin")).statusCode());assertEquals(400,h.json("POST",API+"/"+id,binding(1,"FederatedOther","other",false),auth("admin")).statusCode());assertEquals(404,h.json("POST",API+"/"+Values.id(),binding(1,"FederatedUser","x",false),auth("admin")).statusCode());assertEquals(409,h.json("POST",API+"/"+id,binding(9,"FederatedUser","x",false),auth("admin")).statusCode());for(Object subject:List.of(""," space","space ","a b","é","x".repeat(256),12)){var input=binding(0,"FederatedOther","x",false);input.put("subject",subject);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());}assertEquals(400,h.json("POST",API,binding(0,"Missing","x",false),auth("admin")).statusCode());assertEquals(400,h.json("POST",API,binding(0,"FederatedOther","x",true),auth("admin")).statusCode());for(var bad:List.of(map("extra",1),map("remove","true"))){var input=binding(0,"FederatedOther","x",false);input.putAll(bad);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());}
   for(String invalid:List.of("http://example.org","ftp://example.org","relative","https://user:secret@example.org","https://example.org?x=1","https://example.org#part","https://[")){p.settings.put("OIDC_ISSUER",invalid);assertEquals(false,object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));assertEquals(200,h.get("/login",null).statusCode());}p.settings.put("OIDC_ISSUER",p.origin);for(String key:List.of("OIDC_AUTHORIZATION_URL","OIDC_TOKEN_URL","OIDC_JWKS_URL")){Object old=p.settings.put(key,"https://foreign.example/path");assertEquals(false,object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));p.settings.put(key,old);}p.settings.put("PUBLIC_BASE_URL",h.base()+"/path");assertEquals(false,object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));p.settings.put("PUBLIC_BASE_URL",h.base());p.settings.put("OIDC_CLIENT_ID","");assertEquals(false,object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));p.settings.put("OIDC_CLIENT_ID","test-client");p.settings.put("OIDC_ISSUER","https://example.org/"+"x".repeat(512));assertEquals(false,object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));p.settings.put("OIDC_ISSUER",p.origin);
   assertEquals(400,h.protectedForm("/admin/federation",map("revision","0","username","FederatedOther","subject","other","remove","bad"),auth("admin")).statusCode());assertEquals(302,h.protectedForm("/admin/federation",map("revision","0","username","FederatedOther","subject","other","remove","false"),auth("admin")).statusCode());p.settings.put("OIDC_ENABLED","false");assertEquals(302,h.protectedForm("/admin/federation/"+id,map("revision","1","username","FederatedUser","subject","employee-123","remove","true"),auth("admin")).statusCode());
  }
 }
 static void claims(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){setup(h);long now=System.currentTimeMillis()/1000;var rejected=List.of(map("iss","https://foreign.example"),map("aud",List.of("foreign")),map("nonce","foreign"),map("exp",now-60),map("iat",now+120),map("iat",now-301),map("exp",now+50,"iat",now+60),map("azp","foreign"),map("aud",List.of("test-client","second")),map("sub",""),map("sub"," x"),map("iat","bad"),map("azp",12));for(var bad:rejected){p.claims=bad;assertEquals(401,login(h).statusCode(),bad.toString());}p.claims=Map.of();for(String mode:List.of("unsigned","algorithm","unknown-key","missing-kid")){p.mode=mode;assertEquals(401,login(h).statusCode(),mode);}p.mode="good";for(String raw:List.of("{","{}","{\"id_token\":\"bad\"}")){p.tokenOverride=raw.getBytes(StandardCharsets.UTF_8);assertEquals(401,login(h).statusCode());}p.tokenOverride=null;for(String raw:List.of("{","{\"keys\":[]}",new JWKSet(Collections.nCopies(17,p.key.toPublicJWK())).toString(),new JWKSet(p.key).toString(false))){p.keyOverride=raw.getBytes(StandardCharsets.UTF_8);assertEquals(401,login(h).statusCode());}p.keyOverride=null;p.claims=map("aud",List.of("test-client","second"),"azp","test-client");assertEquals(302,login(h).statusCode());assertEquals(200,h.get("/",null).statusCode());
  }
 }
 static void state(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){setup(h);assertEquals(405,h.get("/oidc/start",null).statusCode());assertEquals(403,h.form("/oidc/start",map("csrf","bad"),null).statusCode());assertEquals(400,h.form("/oidc/start",map("csrf",csrf(h.get("/login",null)),"extra","bad"),null).statusCode());assertEquals(405,h.form("/oidc/callback",map(),null).statusCode());assertEquals(400,h.get("/oidc/callback?state=x&code=x",null).statusCode());assertEquals(400,h.get("/oidc/callback?state="+Passwords.token()+"&code=a&error=b",null).statusCode());assertEquals(400,h.get("/oidc/callback?state="+Passwords.token()+"&code=a&extra=b",null).statusCode());assertEquals(400,h.get("/oidc/callback?state=a&state=b&code=x",null).statusCode());
   String callback=returned(h,begin(h));var other=HttpClient.newHttpClient();assertEquals(401,other.send(HttpRequest.newBuilder(URI.create(h.base()+callback)).GET().build(),HttpResponse.BodyHandlers.ofByteArray()).statusCode());assertEquals(302,h.get(callback,null).statusCode());callback=returned(h,begin(h));try(var db=h.store.open()){db.update("UPDATE os_oidc_challenge SET expires_at=0");db.connection.commit();}assertEquals(401,h.get(callback,null).statusCode());String first=returned(h,begin(h));String second=returned(h,begin(h));assertEquals(401,h.get(first,null).statusCode());assertEquals(302,h.get(second,null).statusCode());
   callback=returned(h,begin(h));p.settings.put("OIDC_CLIENT_SECRET","changed");assertEquals(401,h.get(callback,null).statusCode());p.settings.put("OIDC_CLIENT_SECRET","synthetic-secret");var args=query(URI.create(returned(h,begin(h))).getRawQuery());args.remove("code");args.put("error","access_denied");assertEquals(401,h.get("/oidc/callback?"+Oidc.encoded(new LinkedHashMap<>(args)),null).statusCode());args=query(URI.create(returned(h,begin(h))).getRawQuery());args.put("iss","https://foreign.example");assertEquals(401,h.get("/oidc/callback?"+Oidc.encoded(new LinkedHashMap<>(args)),null).statusCode());callback=returned(h,begin(h));try(var db=h.store.open()){db.update("UPDATE os_oidc_challenge SET envelope='unreadable'");db.connection.commit();}assertEquals(503,h.get(callback,null).statusCode());assertEquals(401,h.get(callback,null).statusCode());
  }
 }
 static void authority(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){String binding=setup(h);for(String column:List.of("active","api_only","password_reset_required")){String callback=returned(h,begin(h));int bad=column.equals("active")?0:1,good=1-bad;try(var db=h.store.open()){db.update("UPDATE os_user SET "+column+"=? WHERE name='FederatedUser'",bad);db.connection.commit();}assertEquals(401,h.get(callback,null).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET "+column+"=? WHERE name='FederatedUser'",good);db.connection.commit();}}
   assertEquals(302,login(h).statusCode());p.settings.put("OIDC_CLIENT_SECRET","changed");assertEquals(302,h.get("/",null).statusCode());p.settings.put("OIDC_CLIENT_SECRET","synthetic-secret");assertEquals(302,login(h).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_oidc_binding WHERE binding_id=?",binding);db.connection.commit();}assertEquals(302,h.get("/",null).statusCode());assertEquals(401,login(h).statusCode());result(h.json("POST",API,binding(0,"FederatedUser","employee-123",false),auth("admin")));p.afterToken=()->p.settings.put("OIDC_ENABLED","false");assertEquals(503,login(h).statusCode());p.afterToken=()->{};p.settings.put("OIDC_ENABLED","true");p.afterToken=()->p.settings.put("OIDC_CLIENT_SECRET","changed");assertEquals(401,login(h).statusCode());p.afterToken=()->{};p.settings.put("OIDC_CLIENT_SECRET","synthetic-secret");assertEquals(302,login(h).statusCode());p.settings.put("OIDC_TOKEN_URL","invalid");assertEquals(302,h.get("/",null).statusCode());h.login("admin");assertEquals(200,h.get("/",null).statusCode());
  }
 }
 static void providerFailures(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){setup(h);for(String mode:List.of("error","redirect")){p.mode=mode;var response=login(h);assertEquals(502,response.statusCode());assertFalse(html(response).contains("private-provider-error"));}p.mode="good";p.tokenOverride=new byte[65537];assertEquals(502,login(h).statusCode());p.tokenOverride=null;p.keyOverride=new byte[65537];assertEquals(502,login(h).statusCode());p.keyOverride=null;String callback=returned(h,begin(h));p.server.stop(0);assertEquals(502,h.get(callback,null).statusCode());h.login("admin");assertEquals(200,h.get(API,null).statusCode());}
 }
 static void capacity(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){setup(h);long now=System.currentTimeMillis();try(var db=h.store.open()){var existing=db.one("SELECT * FROM os_oidc_binding");for(int n=1;n<1000;n++)db.update("INSERT INTO os_oidc_binding(binding_id,issuer,subject,user_id,revision) VALUES(?,?,?,?,1)",id(),p.origin,"subject-"+n,id());for(int n=0;n<1000;n++)db.update("INSERT INTO os_oidc_challenge(state_hash,session_hash,expires_at,configuration,envelope) VALUES(?,?,?,?,?)",Passwords.tokenHash(id()),Passwords.tokenHash(id()),now+300000,"synthetic","synthetic");db.connection.commit();}h.account("FederationCapacity","agent");assertEquals(400,h.json("POST",API,binding(0,"FederationCapacity","new-subject",false),auth("admin")).statusCode());assertEquals(429,h.form("/oidc/start",map("csrf",csrf(h.get("/login",null))),null).statusCode());try(var db=h.store.open()){db.update("UPDATE os_oidc_challenge SET expires_at=0");db.connection.commit();}assertEquals(302,login(h).statusCode());}
 }
 static void duplicateKeys(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())) {
   var generator=java.security.KeyPairGenerator.getInstance("RSA");generator.initialize(1024);var pair=generator.generateKeyPair();var weak=new RSAKey.Builder((java.security.interfaces.RSAPublicKey)pair.getPublic()).keyID("current-key").build();
   long now=System.currentTimeMillis();String head=Base64.getUrlEncoder().withoutPadding().encodeToString(JSON.writeValueAsBytes(map("alg","RS256","kid","current-key")));String payload=Base64.getUrlEncoder().withoutPadding().encodeToString(JSON.writeValueAsBytes(map("iss",p.origin,"sub","employee-123","aud",List.of("test-client"),"iat",now/1000,"exp",now/1000+120,"nonce","test-nonce")));var signature=java.security.Signature.getInstance("SHA256withRSA");signature.initSign(pair.getPrivate());signature.update((head+"."+payload).getBytes(StandardCharsets.US_ASCII));String raw=head+"."+payload+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(signature.sign());
   byte[] token=JSON.writeValueAsBytes(map("id_token",raw)),keys=new JWKSet(List.of(p.key.toPublicJWK(),weak)).toString().getBytes(StandardCharsets.UTF_8);
   assertThrows(Failure.class,()->Oidc.subject(Oidc.settings(h.store),"test-nonce",token,keys,now));
  }
 }
 static void edges(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())) {
   setup(h);p.settings.put("OIDC_TOKEN_URL","http://127.0.0.1:1/token");assertEquals(false,object(result(h.get(API,auth("admin"))).get("configuration")).get("ready"));p.settings.put("OIDC_TOKEN_URL",p.origin+"/token");p.mode="empty-kid";assertEquals(401,login(h).statusCode());p.mode="good";
   long now=System.currentTimeMillis()/1000;p.claims=map("exp",now+10,"iat",now+20);assertEquals(401,login(h).statusCode());p.claims=Map.of();p.keyOverride=new JWKSet(new com.nimbusds.jose.jwk.gen.ECKeyGenerator(Curve.P_256).keyID("current-key").generate().toPublicJWK()).toString().getBytes(StandardCharsets.UTF_8);assertEquals(401,login(h).statusCode());
   var generator=java.security.KeyPairGenerator.getInstance("RSA");generator.initialize(1024);var pair=generator.generateKeyPair();p.keyOverride=new JWKSet(new RSAKey.Builder((java.security.interfaces.RSAPublicKey)pair.getPublic()).keyID("current-key").build()).toString().getBytes(StandardCharsets.UTF_8);assertEquals(401,login(h).statusCode());p.keyOverride=null;
   assertEquals(400,h.get("/oidc/callback?code=x",null).statusCode());assertEquals(400,h.get("/oidc/callback?state="+Passwords.token(),null).statusCode());var args=query(URI.create(returned(h,begin(h))).getRawQuery());args.remove("iss");assertEquals(302,h.get("/oidc/callback?"+Oidc.encoded(new LinkedHashMap<>(args)),null).statusCode());
   ((CookieManager)h.client.cookieHandler().orElseThrow()).getCookieStore().removeAll();String changed=returned(h,begin(h));p.settings.put("OIDC_CLIENT_SECRET","changed");assertEquals(401,h.get(changed,null).statusCode());p.settings.put("OIDC_CLIENT_SECRET","synthetic-secret");
   String tampered=returned(h,begin(h));try(var db=h.store.open()){var challenge=db.one("SELECT * FROM os_oidc_challenge");var material=Outbox.decrypt(h.store.secret,challenge.get("envelope").toString());material.put("verifier","wrong-verifier");db.update("UPDATE os_oidc_challenge SET envelope=?",Outbox.encrypt(h.store.secret,JSON.writeValueAsString(material)));db.connection.commit();}assertEquals(502,h.get(tampered,null).statusCode());
   try {Thread.currentThread().interrupt();assertThrows(Failure.class,()->Oidc.request(p.origin+"/keys",Map.of()));assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}
  }
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  try(var p=new Provider(h.store,h.base())){setup(h);String callback=returned(h,begin(h));try(var pool=Executors.newFixedThreadPool(2)){var latch=new CountDownLatch(1);var a=pool.submit(()->{latch.await();return h.get(callback,null).statusCode();});var b=pool.submit(()->{latch.await();return h.get(callback,null).statusCode();});latch.countDown();assertEquals(Set.of(302,401),Set.of(a.get(),b.get()));}assertEquals(1,p.tokenCalls);}
 }
}
